function DirectionalDialog:OnInitialize()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self.activityUuid = self.controller.Argument.parameters.activityUuid
        cs_coroutine.yield_return(self:LoadScene())
        local isFinish = false
        GameUtils.Request(
                Interfaces.TimedCopyHome,
                { activityUuid = self.activityUuid },
                function(request, response)
                    isFinish = true
                    if checkInt(response.errCode) == 0 then
                        --printInfo("=========>>"..table.dump(response.data.questInfo))
                        DirectionalFightComponent:InitialDojo(response.data)--这边初始的数据供其他子节点使用
                        DirectionalFightComponent:SetArgVo()
                    end
                end
        )
        while not isFinish do
            coroutine.yield()
        end
        self:InitData()
        for k, v in pairs(self.questInfo) do
            local point = self.scenePointParent.transform:Find(k)
            table.insert(self.scenePointList, point)
            coroutine.yield(self:LoadSelectedPrefab(k, v))
        end
        SetButtonAction(self.FontStyleButton, function()
            self:OnClickFontStyleButton()
            -----test
            --UIModule.OpenDialog({ id = Constants.UITypeIds.UIFightTeamChoose, parameters = {levelId = self.ids[self.selectLevelLuaIndex]}}, {

            --    {id = Constants.UITypeIds.DirectionalDialog}
            --})
            -----
        end)
    end))
    return coWait
end

