---浅拷贝DirectionalFightComponent的数据，维护的时候统一维护
function DirectionalDialog:InitData()
    self.questInfo = DirectionalFightComponent.questInfo
    ---@region将当天开启的副本置于list的首位
    local pos
    local value
    local hasOpen = false
    local lastPassedQuestId = DirectionalFightComponent:GetLastPassedQuestId()
    local isLastPassedQuestOpened = false
    local lastPassedQuestVo
    if not isNull(lastPassedQuestId) then
        isLastPassedQuestOpened = DirectionalFightComponent:IsQuestOpened(lastPassedQuestId)
        lastPassedQuestVo = QuestConfMgr:GetInstance():GetQuestVoById(lastPassedQuestId)
        isLastPassedQuestOpened = true
    end
    if isLastPassedQuestOpened then
        for k, v in pairs(self.questInfo) do
            if checkInt(v.type) == checkInt(lastPassedQuestVo.type) then
                hasOpen = true
                pos = k
                value = v
                break
            end
        end
    else
        for k, v in pairs(self.questInfo) do
            if checkInt(v.isOpen) == 1 then
                hasOpen = true
                pos = k
                value = v
                break
            end
        end
    end
    if hasOpen then
        table.remove(self.questInfo, pos)
        table.insert(self.questInfo, 1, value)
    end
    --周日3个副本都能打的情况下,当前副本次数用完后,自动转换至其他有剩余次数的副本
    if not DirectionalFightComponent:HasWinCount(self.questInfo[1].type) then
        for k, v in pairs(self.questInfo) do
            if checkInt(v.isOpen) == 1 and DirectionalFightComponent:HasWinCount(v.type) then
                local a = clone(self.questInfo[1])
                self.questInfo[1] = v
                self.questInfo[k] = a
                break
            end
        end
    end
    ---@endregion
end

function DirectionalDialog:LoadScene()
    if not isNull(self.sceneGo) then
        printInfo("sceneGo not null")
        return
    end
    local go = GameUtils.LoadBundleSync("Prefabs/Directional/DirectionalScene.prefab", nil, false, true)
    table.insert(self.loaderGoList, go)
    go.name = "DirectionalScene"
    self.sceneGo = go
    self.scenePointParent = go.transform:Find("PointParent")
    self.sceneCamera = go.transform:Find("Camera")
end

---加载左侧用于旋转的三个prefab
---@param index number self.scenePointList的索引，和self.questInfo的索引是对应的
function DirectionalDialog:LoadSelectedPrefab(index)
    --printInfo(self.questInfo[index].type.."===="..index)
    local data = CfUtils.GetCfVo(AutoIds.IdSetting933, "DirectionalTypeVo", tostring(self.questInfo[index].type))
    self.typeData[index] = data --做缓存，避免后面用到时重复调用方法取值
    printInfo("typeData=======>>" .. table.dump(data))
    local path = string.format(data.instancePath)
    local loader = ResourceModule.LoadBundleAsync(path, nil, true)
    while not loader.IsSuccess do
        cs_coroutine.yield_return()
    end
    if not loader.IsError then
        local go = loader:Instantiate()-- GameObject.Instantiate(loader.ResultObject)
        table.insert(self.loaderGoList, go)
        local parent = self.scenePointList[index].transform
        go.transform:SetParent(parent)
        go.transform.localPosition = Vector3.zero
        go.transform.localRotation = Quaternion.identity
        go.transform.localScale = Vector3.one
        ---未开启状态更换材质球
        if not (checkNumber(self.questInfo[index].isOpen) == 1) then
            self:SetMatVectorArg(go, LockedMaterialParameters[tostring(self.questInfo[index].type)])
            --local loaderMat = ResourceModule.LoadBundleSync(data.lockMaterial, nil, true)
            ----local loaderMat = ResourceModule.LoadBundleSync("Scenes/Directional/Matertial/DirectionalInstance02_mat_Lock.mat", nil, true)
            --if loaderMat.IsSuccess then
            --    table.insert(self.loaderGoList, loaderMat)
            --    go.gameObject:GetComponent(typeof(MeshRenderer)).material = loaderMat.ResultObject
            --else
            --    loaderMat:Release(true)
            --end
        end
        ---点击事件
        --KTool.GetOrAddComponent(go.gameObject, typeof(UIEventProxy)).onPointerClick = function()
        --    self:OnClickSelectedPrefab(index)
        --end
        local tap = go.gameObject:EnsureComponent(typeof(QuickTap))
        tap.onTap:AddListener(function(gesture)
            self:OnClickSelectedPrefab(index)
        end)

        ---加载头像UI
        local headGo = CfUtils.InstantiateGo(self.HeadItem, self.controller.gameObject)
        local headGoEnv = CfUtils.GetLuaScr(headGo, "Game.UI.DirectionalFight.DirectionalHeadNode")
        table.insert(self.headGoList, headGo)
        headGoEnv:SetTargetNode(parent.gameObject, self.sceneCamera)
        headGoEnv:FreshBaseUI({
            type = self.questInfo[index].type,
            iconPath = data.battleSelection,
            isOpen = false,-- self.questInfo[index].isOpen,  隐藏
            openTime = data.OpenDescr,
            winTime = DirectionalFightComponent:GetWinCountText(self.questInfo[index].type),
            isFirst = index == 1
        })
        headGoEnv:SetBtnCallBack(function()
            self:OnClickSelectedPrefab(index)
        end)
        if index == 1 then
            --刷新当前选中的
            self:FreshRightData(index)
        end
        KTool.SetActive(headGo, true)
    end
    loader:Release()
    loader = nil
end

function DirectionalDialog:SetMatVectorArg(model, propMap)
    local skin = model.gameObject:GetComponent(typeof(CS.UnityEngine.MeshRenderer))
    local block = CS.UnityEngine.MaterialPropertyBlock()
    skin:GetPropertyBlock(block)
    for k, v in pairs(propMap) do
        if type(v) == "number" then
            block:SetFloat(k, v)
        else
            block:SetVector(k, v)
        end
    end
    skin:SetPropertyBlock(block)
end

