---@param index number self.questInfo的索引
function DirectionalDialog:OnClickSelectedPrefab(index)
    if index ~= self.selectLuaIndex then
        UIRaycastBlocker:AddCondition("DirectionalDialogOnClickSelectedPrefab")
        CriWareUtils.PlaySe(uiSheets.UI_Menu.path, uiSheets.UI_Menu.ui_directional_change)
        --前一个的UI头像状态调整
        local preSelectedHeadEnv = CfUtils.GetLuaScr(self.headGoList[self.selectLuaIndex], "Game.UI.DirectionalFight.DirectionalHeadNode")
        preSelectedHeadEnv:SetSelectedScale(false)
        local selectedHeadEnv = CfUtils.GetLuaScr(self.headGoList[index], "Game.UI.DirectionalFight.DirectionalHeadNode")
        selectedHeadEnv:SetSelectedScale(true)
        --转120度
        local rotate = self:GetRotate(index)
        local startRotation = self.scenePointParent.transform.localEulerAngles
        self.scenePointParent:DOLocalRotate(startRotation + rotate, 0.5).onComplete = (function()
            UIRaycastBlocker:RemoveCondition("DirectionalDialogOnClickSelectedPrefab")
            self.selectLuaIndex = index
            self:FreshRightData(index)
        end)
    end
end

function DirectionalDialog:GetRotate(targetIndex)
    if self.selectLuaIndex == 1 then
        return (targetIndex - self.selectLuaIndex) == 2 and NormalizedRotate or AntiNormalizedRotate
    else
        return (targetIndex - self.selectLuaIndex) == -1 and NormalizedRotate or AntiNormalizedRotate
    end
end

---@param index number self.selectLuaIndex
function DirectionalDialog:FreshRightData(index)
    local questData = self.questInfo[index]
    self.ids = string.split(CfUtils.GetIdGroupData(AutoIds.IdSetting931, checkString(questData.type), "ids")[1], ";")
    local questId
    local data
    if checkNumber(questData.questId) == 0 then
        questId = self.ids[1]
    else
        local nextLevelVo = DirectionalFightComponent:GetNextDifficultyQuestData(questData.questId)
        local isNextLevelUnlock = false
        if not isNull(nextLevelVo) then
            --有下一关卡（不是最高难度）
            isNextLevelUnlock = DirectionalFightComponent:IsTeamRatingConditionMeet(nextLevelVo.regionLevel)
        end
        if isNextLevelUnlock then
            questId = nextLevelVo.id
        else
            questId = questData.questId
        end
    end
    data = QuestConfMgr:GetInstance():GetQuestVoById(questId)
    self:FreshRightUI(data)
end

function DirectionalDialog:FreshRightUI(data)
    --DirectionalFightComponent:TryOpenDifficultyUnlockDialog(data.id)
    ---名字
    self.TxtName.text = data.name

    ---@region难度图标
    --local ratingId = cardComponent:GetRatingId()
    local isMeetPassCondition = checkNumber(self.questInfo[self.selectLuaIndex].questId) >= checkNumber(data.unlockNum)
    --local isMeetTeamRatingCondition = checkNumber(ratingId) >= checkNumber(data.regionLevel)
    local isMeetAllCondition = isMeetPassCondition --and isMeetTeamRatingCondition --同时满足两个条件
    --CfUtils.FillImage(self.ImgDifficulty, DirectionalFightComponent:GetLevelIconPath2(data.regionLevel))
    ---@endregion
    
    --{{{ 怪物详情
    ---@type QuestConfMgr
    local questConfMgr  = QuestConfMgr:GetInstance()
    
    local levelId = data.id
    ---@type table<number, WaveVo>
    local allQuestWaveVo = questConfMgr:GetAllQuestLineupVo(levelId)
    local monsterDataList = {}
    for _, waveVo in ipairs(allQuestWaveVo) do
        for i = 1, #waveVo.wave1NpcId do
            local monsterId = waveVo.wave1NpcId[i]
            local attribute = waveVo.attribute[i]
            local monsterRare   = 0
            local monsterTypeVo = cardConfMgr:GetMonsterTypeVoById(monsterId)
            if monsterTypeVo.role > 0 then
                local cardData = cardConfMgr:GetCardByRefId(monsterTypeVo.mode)
                monsterRare = cardData.rare
            else
                monsterRare = monsterTypeVo.monsterClass
            end
            local monsterData = {
                id          = monsterId,
                defaultSkin = monsterTypeVo.skinId,
                rare        = monsterRare,
                --hpPercent   = 1,
                --energy      = 0,
                attribute   = attribute,
            }
            table.insert(monsterDataList, monsterData)
        end
    end
    
    local count = #monsterDataList
    local monsterDataList2 = {}
    if count > 3 then
        local index = math.floor(count/2) - 1
        table.insert(monsterDataList2, monsterDataList[index])
        table.insert(monsterDataList2, monsterDataList[index + 1])
        table.insert(monsterDataList2, monsterDataList[index + 2])
    else
        monsterDataList2 = monsterDataList
    end
    
    --self.monstersDetail:FillCardAliveState(memberAliveList)
    self.monstersDetail:FillMonsters(monsterDataList2, nil, function()
        CfUtils.DialogOpen(Constants.UITypeIds.UIBossDetailDialog, {levelId = levelId})
    end)
    --}}}

    ---@region 奖励部分
    local rewardVo = RewardConfMgr:GetInstance():GetTeamShowRewardData(data.id)
    self.CommonGoodsList.Env:FreshBaseUI(rewardVo)
    ---@endregion
    ---@region 确定部分
    local isOpen = checkInt(self.questInfo[self.selectLuaIndex].isOpen) == 1--
    if isOpen then
        --开放
        local isDuring, seconds = DirectionalFightComponent:IsDirectionalFightDuring()
        KTool.SetActive(self.ImgOpen, false)
        if isDuring then
            --开启
            local wonCount = 0;
            for i, v in pairs(self.questInfo) do
                wonCount = wonCount + checkNumber(v.questAtNum)
            end
            local daliyCountLimit = wonCount >= DirectionalFightComponent.maxDailyWinCount
            local isWinCountLimit = checkNumber(self.questInfo[self.selectLuaIndex].questAtNum) >= DirectionalFightComponent.maxWinCountOfType--通过次数已达上限
            if isWinCountLimit or daliyCountLimit then
                --挑战已达上限
                KTool.SetActive(self.ImgClock, true)
                KTool.SetActive(self.ImgWinCount, true)
                self.TextClockDesc.text = localize("距离结束")
                self.TextClock.Env:StartLeftSecond(seconds, 2, function()
                    self:FreshRightData(self.selectLuaIndex)
                end)
                self.TxtWinCount.text = DirectionalFightComponent:GetWinCountText(self.questInfo[self.selectLuaIndex].type)
                self.FontStyleButton:ResetFontStyle("B17", localize("挑战已上限"))
                Events.Broadcast(Constants.EventNames.ActivityRedPointChange, self.activityUuid, -1)
            else
                if isMeetAllCondition then
                    --满足条件
                    KTool.SetActive(self.ImgClock, true)
                    KTool.SetActive(self.ImgWinCount, true)
                    self.TextClockDesc.text = localize("距离结束")
                    self.TextClock.Env:StartLeftSecond(seconds, 2, function()
                        self:FreshRightData(self.selectLuaIndex)
                    end)
                    self.TxtWinCount.text = DirectionalFightComponent:GetWinCountText(self.questInfo[self.selectLuaIndex].type)
                    self.FontStyleButton:ResetFontStyle("B1", localize("开始战斗"))
                else
                    --锁
                    KTool.SetActive(self.ImgClock, false)
                    KTool.SetActive(self.ImgWinCount, false)
                    self.FontStyleButton:ResetFontStyle("B4")
                end
            end
        else
            if seconds > 0 then
                --开启前(未开启)
                KTool.SetActive(self.ImgClock, true)
                KTool.SetActive(self.ImgWinCount, true)
                self.TextClockDesc.text = localize("距离开启")
                self.TextClock.Env:StartLeftSecond(seconds, 2, function()
                    self:FreshRightData(self.selectLuaIndex)
                end)
                self.TxtWinCount.text = DirectionalFightComponent:GetWinCountText(self.questInfo[self.selectLuaIndex].type)
                self.FontStyleButton:ResetFontStyle("B17", localize("未开启"))
            else
                --开启后(挑战已结束)
                KTool.SetActive(self.ImgClock, false)
                KTool.SetActive(self.ImgWinCount, true)
                self.TxtWinCount.text = DirectionalFightComponent:GetWinCountText(self.questInfo[self.selectLuaIndex].type)
                self.FontStyleButton:ResetFontStyle("B17", localize("挑战已结束"))
            end
        end

    else
        --未开放
        KTool.SetActive(self.ImgClock, false)
        KTool.SetActive(self.ImgOpen, true)
        KTool.SetActive(self.ImgWinCount, false)
        local txt = self.typeData[self.selectLuaIndex].OpenDescr
        self.TextOpen.text = txt
        self.FontStyleButton:ResetFontStyle("B17", localize("未开放"))
    end
    CS.UnityEngine.UI.LayoutRebuilder.ForceRebuildLayoutImmediate(self.ImgWinCount)
    ---@endregion
end

function DirectionalDialog:OnClickFontStyleButton()
    local questId = self.ids[self.selectLevelLuaIndex]
    local questData = QuestConfMgr:GetInstance():GetQuestVoById(questId)
    --local ratingId = cardComponent:GetRatingId()
    local isMeetPassCondition = checkNumber(self.questInfo[self.selectLuaIndex].questId) >= checkNumber(questData.unlockNum)
    --local isMeetTeamRatingCondition = checkNumber(ratingId) >= checkNumber(questData.regionLevel)

    local isMeetAllCondition = isMeetPassCondition --and isMeetTeamRatingCondition --同时满足两个条件
    local isOpen = checkInt(self.questInfo[self.selectLuaIndex].isOpen) == 1--
    if isOpen then
        --开放
        local isDuring, seconds = DirectionalFightComponent:IsDirectionalFightDuring()
        if isDuring then
            --开启
            local wonCount = 0;
            for i, v in pairs(self.questInfo) do
                wonCount = wonCount + checkNumber(v.questAtNum)
            end
            local daliyCountLimit = wonCount >= DirectionalFightComponent.maxDailyWinCount
            local isWinCountLimit = checkNumber(self.questInfo[self.selectLuaIndex].questAtNum) >= DirectionalFightComponent.maxWinCountOfType--通过次数已达上限
            if isWinCountLimit or daliyCountLimit then
                --挑战已达上限
                GameUtils.Toast(localize("今日作战已上限"))
            else
                if isMeetAllCondition then
                    --满足条件
                    --进入编队
                    UIModule.OpenDialog({ id = Constants.UITypeIds.UIFightTeamChoose, parameters = { levelId = self.ids[self.selectLevelLuaIndex], freeTimesRemain = 0, activityUuid = self.activityUuid } }, {
                        { id = Constants.UITypeIds.DirectionalDialog }
                    })
                else
                    --锁
                    --local curLevel = questData.regionLevel
                    local preLevel = checkNumber(questData.regionLevel) - 1
                    --local curLevelVo = CfUtils.GetCfVo(AutoIds.IdSetting121, "CardUpgradeStarLimitVo", curLevel)
                    local preLevelVo = CfUtils.GetCfVo(AutoIds.IdSetting121, "CardUpgradeStarLimitVo", preLevel)
                    GameUtils.Toast(localize("通关难度_preLevel_后解锁", { _preLevel_ = preLevelVo.name }))
                end
            end
        else
            if seconds >= 0 then
                --开启前(未开启)
                GameUtils.Toast(localize("作战未开启"))
            else
                --开启后(挑战已结束)
                GameUtils.Toast(localize("作战已结束"))
            end
        end
    else
        --未开放
        GameUtils.Toast(localize("作战未开放"))
    end
end

function DirectionalDialog:DisposeLoadRes()
    if not isNull(self.sceneGo) then
        GameObject.Destroy(self.sceneGo)
    end
    for k, v in pairs(self.loaderGoList) do
        if not isNull(v) then
            GameObject.Destroy(v)
            --v:Release(true)
        end
    end

end

function DirectionalDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self:DisposeLoadRes()
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return DirectionalDialog